/**
 * Hosting/datacenter detection for visitor IPs.
 *
 * A scraper or proxy bot behind AWS looks exactly like a reader over HTTP:
 * correct user agent, cookies accepted, one page, gone. The one thing it
 * cannot fake is where the connection comes from, so the ranges below are the
 * networks that belong to clouds, hosting companies and proxy farms rather
 * than to homes.
 *
 * `hosting-ranges.json` is generated by `scripts/build-hosting-ranges.mjs`
 * from two sources: the curated datacenter list at X4BNet/lists_vpn and the
 * per-ASN allocations in iptoasn.com's ip2asn table, filtered to the hosting
 * ASNs listed in that script. It is a sorted, coalesced array of
 * [firstIp, lastIp] pairs as unsigned 32-bit integers, which is why lookups
 * are a binary search and why the file is ~800KB rather than tens of MB.
 *
 * Regenerate it every few months — cloud ranges move:
 *   node scripts/build-hosting-ranges.mjs
 *
 * Being flagged here is deliberately a *downgrade*, not a conviction: a real
 * person on a corporate VPN still counts as a person once the browser beacon
 * proves a browser is running (see app/api/pageview). It only decides what to
 * do with hits that never prove anything.
 */
import ranges from '@/data/hosting-ranges.json'

/** Sorted, non-overlapping [first, last] IPv4 ranges as uint32. */
const RANGES = ranges as unknown as readonly [number, number][]

export function ipv4ToInt(ip: string): number | null {
  const parts = ip.split('.')
  if (parts.length !== 4) return null
  let value = 0
  for (const part of parts) {
    if (!/^\d{1,3}$/.test(part)) return null
    const octet = Number(part)
    if (octet > 255) return null
    value = value * 256 + octet
  }
  return value >>> 0
}

/** True when the address belongs to a cloud, hosting or proxy network. */
export function isHostingIp(ip: string | null | undefined): boolean {
  if (!ip) return false
  // IPv6 is left alone: Vercel hands the proxy IPv4 on this site, and a wrong
  // guess on v6 would be worse than no guess. See build-hosting-ranges.mjs.
  const value = ipv4ToInt(ip)
  if (value === null) return false

  let low = 0
  let high = RANGES.length - 1
  while (low <= high) {
    const mid = (low + high) >> 1
    const [first, last] = RANGES[mid]
    if (value < first) high = mid - 1
    else if (value > last) low = mid + 1
    else return true
  }
  return false
}

/** Exposed for the generator's self-check and for the dashboard footer. */
export const HOSTING_RANGE_COUNT = RANGES.length
